/**
 * One bin of a histogram (G5a): [range] names it for TalkBack („10 bis unter 20 Min.“, the row head of the web's
 * table, which says where a boundary belongs), [count] its height on the scale, [countText] the number on the bin.
 */
@Immutable
data class SbBin(val range: String, val count: Float, val countText: String)

/**
 * Histogram (G5a, spec/02 §3.7 `sb-chart__bars--dense`): equal classes without gaps in the values, all bins grey
 * (chartBar), 2 dp apart on a 1 dp chartAxis base line in a 128 dp plot under one caption line of head room; the
 * count on each bin (caption, text, 2 dp above it); the [edges] (n + 1 boundaries) centred on the edges of the bins
 * and the [unit] once below them, both textMuted and hidden from TalkBack. The count axis starts at 0; [max] = its
 * top (else the largest count; with every count 0 the bins stay empty on the base line, their „0“ on it). TalkBack
 * reads the caption, then one node per bin („10 bis unter 20 Min.: 5“).
 */
@Composable
fun SbHistogram(
    bins: List<SbBin>,
    edges: List<String>,
    unit: String,
    caption: String,
    modifier: Modifier = Modifier,
    max: Float? = null,
) {
    require(bins.isNotEmpty()) { "SbHistogram: no bins" }
    require(edges.size == bins.size + 1) { "SbHistogram: one boundary more than bins" }
    // no entry yet (every count 0): empty bins on the base line, not an error
    val top = max ?: bins.maxOf { it.count }.takeIf { it > 0f } ?: 1f
    require(top > 0f) { "SbHistogram: max must be above 0" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val head = with(LocalDensity.current) { ty.caption.lineHeight.toDp() }
    SbBoundedChartFigure(caption, modifier) {
        Column(Modifier.fillMaxWidth()) {
            Row(
                Modifier
                    .fillMaxWidth()
                    .padding(top = head)
                    .height(t.space.s16 * 2)
                    .drawBehind {
                        val hair = t.borderWidth.hairline.toPx()
                        drawLine(t.x.chartAxis, Offset(0f, size.height - hair / 2f), Offset(size.width, size.height - hair / 2f), hair)
                    },
                horizontalArrangement = Arrangement.spacedBy(t.space.s0_5),
            ) {
                bins.forEach { b ->
                    val share = (b.count / top).coerceIn(0f, 1f)
                    Layout(
                        content = { Text(b.countText, style = text, color = c.text, softWrap = false) },
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxHeight()
                            .drawBehind {
                                val floor = size.height - t.borderWidth.hairline.toPx()
                                drawRect(t.x.chartBar, Offset(0f, floor * (1f - share)), Size(size.width, floor * share))
                            }
                            .clearAndSetSemantics { contentDescription = m.chartPoint(b.range, b.countText) },
                    ) { measurables, constraints ->
                        val p = measurables.first().measure(Constraints())
                        val floor = constraints.maxHeight - t.borderWidth.hairline.toPx()
                        layout(constraints.maxWidth, constraints.maxHeight) {
                            // the count stands on its bin (sb-chart__count), a full bin's in the head room
                            p.placeRelative((constraints.maxWidth - p.width) / 2, (floor * (1f - share) - t.space.s0_5.toPx() - p.height).roundToInt())
                        }
                    }
                }
            }
            SbBinEdges(edges)
            Text(
                unit,
                style = ty.caption,
                color = c.textMuted,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = t.space.s1)
                    .clearAndSetSemantics { },
            )
        }
    }
}

/** The class boundaries under a histogram (`sb-chart__edges`): n + 1 labels centred on the edges of n bins. */
@Composable
private fun SbBinEdges(edges: List<String>) {
    val ty = SebaroTheme.typography
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    Layout(
        content = { edges.forEach { Text(it, style = text, color = SebaroTheme.colors.textMuted, softWrap = false) } },
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = SebaroTheme.tokens.space.s1)
            .clearAndSetSemantics { },
    ) { measurables, constraints ->
        val placeables = measurables.map { it.measure(Constraints()) }
        val step = constraints.maxWidth.toFloat() / (edges.size - 1)
        layout(constraints.maxWidth, placeables.maxOf { it.height }) {
            placeables.forEachIndexed { i, p -> p.placeRelative((i * step - p.width / 2f).roundToInt(), 0) }
        }
    }
}
